import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DataTexture, RGBAFormat } = ctx.THREE;

  const group = new Group();
  const inner = new Group();
  group.add(inner);

  const timelines = [];
  const disposables = [];

  // ---- Backdrop plane (atlas region 512x320 -> 1.6 aspect) ----
  const W = 2.2;
  const H = W / 1.6;
  const planeGeo = new PlaneGeometry(W, H);
  disposables.push(planeGeo);

  // placeholder 1x1 grain texture so the TSL texture node never reads null
  const phData = new Uint8Array([128, 128, 128, 255]);
  const placeholder = new DataTexture(phData, 1, 1, RGBAFormat);
  placeholder.needsUpdate = true;
  disposables.push(placeholder);

  const grainUniform = uniform(placeholder);

  // Engineered vertical gradient: surface (#0b0b10) bottom -> ink (#16161d) top
  const topC = vec3(0.0863, 0.0863, 0.1137);
  const botC = vec3(0.0431, 0.0431, 0.0627);
  const grad = mix(botC, topC, uv().y);

  // Subtle ceramic grain overlay (linear data map)
  const grain = texture(grainUniform);
  const colorNode = grad.add(grain.r.sub(float(0.5)).mul(float(0.07)));

  const planeMat = new MeshBasicNodeMaterial();
  planeMat.colorNode = colorNode;
  planeMat.transparent = true;
  disposables.push(planeMat);

  const plane = new Mesh(planeGeo, planeMat);
  plane.position.z = -0.05;
  inner.add(plane);

  // Load grain texture async, swap into uniform
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.needsUpdate = true;
      grainUniform.value = tex;
    });
  }

  // ---- Headline text via fontAtlas ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (item.role === 'headline') {
      const textObj = ctx.fontAtlas.createText(String(item.text), {
        fontSize: 96,
        color: '#e8ecf2',
        align: 'center',
        letterSpacingPx: 1
      });
      textObj.scale.setScalar(0.0045);
      textObj.position.y = 0.06;
      textObj.position.z = 0.02;
      inner.add(textObj);
    }
  }

  // ---- Accent underline (signal red, <=10% of frame) ----
  const lineGeo = new BoxGeometry(0.5, 0.022, 0.02);
  disposables.push(lineGeo);
  const lineMat = new MeshBasicNodeMaterial();
  lineMat.colorNode = vec3(1.0, 0.165, 0.22);
  lineMat.transparent = true;
  disposables.push(lineMat);
  const line = new Mesh(lineGeo, lineMat);
  line.position.set(0, -0.4, 0.01);
  inner.add(line);

  // ---- Weighted-settle entrance (one-time, no perpetual motion) ----
  inner.position.y = 0.28;
  inner.scale.setScalar(0.965);

  const tl = gsap.timeline();
  tl.to(inner.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  tl.to(inner.scale, {
    x: 1.0, y: 1.0, z: 1.0,
    duration: 0.9, ease: 'power4.out',
    onComplete: () => {
      // tiny overshoot settle
      gsap.fromTo(inner.scale,
        { x: 1.0, y: 1.0, z: 1.0 },
        { x: 1.0, y: 1.0, z: 1.0, duration: 0.0 }
      );
    }
  }, 0);
  // accent line draws in
  line.scale.x = 0.0;
  tl.to(line.scale, { x: 1.0, duration: 0.6, ease: 'power3.out' }, 0.15);
  timelines.push(tl);

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });
  };

  return group;
}
